module verified_serial2parallel(
    input               clk         ,
    input               rst_n       ,
    input               valid_a     ,
    input               data_a      ,

    output  reg            ready_a     ,
    output  reg         valid_b     ,
    output      [5:0]   data_b
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ready_a <= 1'b0;
    end
    else
        ready_a <= 1'b1;
 end

reg [2:0]cnt;
reg [5:0]data_t,data_t1;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin

        data_t <= 'd0;
        cnt <= 'd0;
    end
    else if (valid_a && ready_a) begin

        data_t <= {data_a,data_t[5:1]};


        if(cnt == 'd5)begin
            cnt <= 'd0;
        end
        else begin
            cnt <= cnt + 1'b1;
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_b <= 'd0;
    end
    else if (valid_b== 1'b0 && cnt == 'd5 && valid_a && ready_a) begin
        valid_b <= 'd1;

    end
    else begin
        valid_b <= 'd0;

    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_t1 <= 'd0;
    end
    else if (valid_b) begin
        data_t1 <= data_t;
    end
end

assign data_b = valid_b ? data_t : data_t1;
endmodule

`timescale 1ns/1ns
module verified_signal_generator(
	input clk,
	input rst_n,
	input [1:0] wave_choise,
	output reg [4:0]wave
	);

    reg [4:0] cnt;
    reg flag;


    always@(posedge clk or negedge rst_n) begin
        if(~rst_n)
            cnt <= 0;
        else
            cnt <= wave_choise!=0 ? 0:
                   cnt        ==19? 0:
                   cnt + 1;
    end


    always@(posedge clk or negedge rst_n) begin
        if(~rst_n)
            flag <= 0;
        else
            flag <= wave_choise!=2 ? 0:
                    wave       ==1 ? 1:
                    wave       ==19? 0:
                    flag;
    end



    always@(posedge clk or negedge rst_n) begin
        if(~rst_n)
            wave <= 0;
        else
            case(wave_choise)
                0      : wave <= cnt == 9? 20    :
                                 cnt ==19? 0     :
                                 wave;
                1      : wave <= wave==20? 0     : wave+1;
                2      : wave <= flag==0 ? wave-1: wave+1;
                default: wave <= 0;
            endcase
    end
endmodule

`timescale 1ns/1ns

module verified_traffic_light
    (
		input rst_n,
      input clk,
      input pass_request,
		  output wire[7:0]clock,
      output reg red,
		  output reg yellow,
		  output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;
	reg [7:0] cnt;
	reg [1:0] state;
	reg p_red,p_yellow,p_green;


always @(posedge clk or negedge rst_n)
    begin
        if(!rst_n)
        begin
			state <= idle;
			p_red <= 1'b0;
			p_green <= 1'b0;
			p_yellow <= 1'b0;
        end
        else case(state)
		idle:
			begin
				p_red <= 1'b0;
				p_green <= 1'b0;
				p_yellow <= 1'b0;
				state <= s1_red;
			end
		s1_red:
			begin
				p_red <= 1'b1;
				p_green <= 1'b0;
				p_yellow <= 1'b0;
				if (cnt == 3)
					state <= s3_green;
				else
					state <= s1_red;
			end
		s2_yellow:
			begin
				p_red <= 1'b0;
				p_green <= 1'b0;
				p_yellow <= 1'b1;
				if (cnt == 3)
					state <= s1_red;
				else
					state <= s2_yellow;
			end
		s3_green:
			begin
				p_red <= 1'b0;
				p_green <= 1'b1;
				p_yellow <= 1'b0;
				if (cnt == 3)
					state <= s2_yellow;
				else
					state <= s3_green;
			end
		endcase
	end

always @(posedge clk or negedge rst_n)
      if(!rst_n)
			cnt <= 7'd10;
		else if (pass_request&&green&&(cnt>10))
			cnt <= 7'd10;
		else if (!green&&p_green)
			cnt <= 7'd60;
		else if (!yellow&&p_yellow)
			cnt <= 7'd5;
		else if (!red&&p_red)
			cnt <= 7'd10;
		else cnt <= cnt -1;
 assign clock = cnt;

always @(posedge clk or negedge rst_n)
        if(!rst_n)
			begin
				yellow <= 1'd0;
				red <= 1'd0;
				green <= 1'd0;
			end
		else
			begin
				yellow <= p_yellow;
				red <= p_red;
				green <= p_green;
			end

endmodule

`timescale 1ns/1ns
module verified_width_8to16(
	input 				   clk 		,
	input 				   rst_n		,
	input				      valid_in	,
	input	   [7:0]		   data_in	,

 	output	reg			valid_out,
	output   reg [15:0]	data_out
);
reg 	[7:0]		data_lock;
reg 				flag	   ;

always @(posedge clk or negedge rst_n ) begin
	if(!rst_n)
		data_lock <= 'd0;
	else if(valid_in && !flag)
		data_lock <= data_in;
end

always @(posedge clk or negedge rst_n ) begin
	if(!rst_n)
		flag <= 'd0;
	else if(valid_in)
		flag <= ~flag;
end

always @(posedge clk or negedge rst_n ) begin
	if(!rst_n)
		valid_out <= 'd0;
	else if(valid_in && flag)
		valid_out <= 1'd1;
	else
		valid_out <= 'd0;
end

always @(posedge clk or negedge rst_n ) begin
	if(!rst_n)
		data_out <= 'd0;
	else if(valid_in && flag)
		data_out <= {data_lock, data_in};
end

endmodule
